const cardDetails = await browserjs(tabId, () => {
  // Let's get the cards containing Lollihop and Le Creuset
  const result = [];
  const names = ['Lollihop', 'Le Creuset'];

  for (const name of names) {
    const el = Array.from(document.querySelectorAll('*')).find(e => e.textContent === name && e.tagName.match(/^H[1-6]|SPAN|P|DIV$/));
    if (el) {
      // Find its card container
      let cur = el;
      while (cur && cur.parentElement && !cur.getAttribute('class')?.includes('Card') && !cur.getAttribute('class')?.includes('card')) {
        cur = cur.parentElement;
      }
      result.push({
        name,
        cardText: cur ? cur.innerText : el.parentElement?.parentElement?.innerText
      });
    }
  }
  return result;
});

